def compute(vars):
    threshold = 40000
    v2018 = vars["v1"]
    v2017 = vars["v2"]

    if v2018 < threshold:
        result = 2018
    elif v2017 < threshold:
        result = 2017
    else:
        result = None

    return {
        "value": result,
        "trace": {
            "threshold": threshold,
            "2018_expense": v2018,
            "2017_expense": v2017,
            "2018_less_than_threshold": v2018 < threshold,
            "2017_less_than_threshold": v2017 < threshold,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
